# Let me analyze the 8s components properly
from collections import deque

n, m = len(grid), len(grid[0])

visited = [[False] * m for _ in range(n)]
components = []

for r in range(n):
    for c in range(m):
        if grid[r][c] == 8 and not visited[r][c]:
            component = []
            queue = deque([(r, c)])
            visited[r][c] = True
            while queue:
                cr, cc = queue.popleft()
                component.append((cr, cc))
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < n and 0 <= nc < m and not visited[nr][nc] and grid[nr][nc] == 8:
                        visited[nr][nc] = True
                        queue.append((nr, nc))
            components.append(component)

print(f"Number connected 8-components: {len(components)}")
for i, comp in enumerate(components):
    print(f"Component {i}: {len(comp)} cells")

# Check regions formed by rows [3, 7, 13] and cols [1, 6, 7]
# These divide the grid into rectangular regions

marker_rows = [3, 7, 13]
marker_cols = [1, 6, 7]

# Get the ranges they define
row_ranges = list((0, marker_rows[0]), *(
    (marker_rows[i], marker_rows[i+1]) for i in range(len(marker_rows)-1)
), (marker_rows[-1], nl))

col_ranges = list((0, marker_cols[0]), *(
    (marker_cols[i], marker_cols[i+1]) for i in range(len(marker_cols)-1)
), (marker_cols[-1], ml))

print("Row ranges:", row_ranges)
print("Col ranges:", col_ranges)

# Now check: for cells NOT in marker rows/cols, do they stay 4 or become 2?
stayed_4_nonmarker = []
became_2_nonmarker = []

for r in range(nl):
    for c in range(ml):
        if r not in marker_rows and c not in marker_cols:
            if demo_in[r][c] == 4:
                if demo_out[r][c] == 4:
                    stayed_4_nonmarker.append((r, c))
                elif demo_out[r][c] == 2:
                    became_2_nonmarker.append((r, c))

print(f"\nCells with 4, not in marker rows/cols that stayed 4: {stayed_4_nonmarker}")
print(f"Cells with 4, not in marker rows/cols that became 2: {became_2_nonmarker}")

# Verify the pattern matches the demo output
marker_rows = [3, 7, 13]  # rows with only 4
marker_cols = [1, 6, 7]   # cols with only 4

nl, ml = 18, 15

def compute_expected_output(input_grid):
    nl, ml = len(input_grid), len(input_grid[0])
    # Find marker rows/cols
    marker_rows = set(r for r in range(nl) if all(input_grid[r][c] == 4 for c in range(ml)))
    marker_cols = set(c for c in range(ml) if all(input_grid[r][c] == 4 for r in range(nl)))

    output = []
    for r in range(nl):
        row_out = []
        for c in range(ml):
            if r in marker_rows or c in marker_cols:
                row_out.append(2)
            elif input_grid[r][c] == 8:
                row_out.append(8)
            else:  # input is 4 and NOT in marker row/col
                row_out.append(4)
        output.append(row_out)
    return output

expected = compute_expected_output(demo_in)
matches = expected == demo_out
print(f"Pattern matches demo output: {matches}")

# Show differences if any
if not matches:
    for r in range(nl):
        for c in range(ml):
            if expected[r][c] != demo_out[r][c]:
                print(f"Mismatch at ({r},{c}): expected {expected[r][c]}, got {demo_out[r][c]}")

